import userEvent from "@testing-library/user-event";
import { useState } from "react";
import { describe, expect, it, vi } from "vitest";
import {
  act,
  fireEvent,
  render,
  screen,
  waitFor,
} from "../../../test-utils/render";
import AppDownloadStack from "../index";

const apps = [
  { icon: "https://example.com/github.png", id: 1, name: "GitHub" },
  { icon: "https://example.com/figma.png", id: 2, name: "Figma" },
];

/** The component's own `setTimeout` gates, mirrored so the clock can skip them. */
const DOWNLOAD_DURATION_MS = 3000;
const RESET_DELAY_MS = 1000;

/** Upper bound on how many real frames a Motion transition is given to finish. */
const MAX_TRANSITION_FRAMES = 120;

/** Skips one of the component's faked `setTimeout` gates. */
const skipGate = (ms: number) => {
  act(() => {
    vi.advanceTimersByTime(ms);
  });
};

const nextFrame = () =>
  new Promise<void>((resolve) => {
    requestAnimationFrame(() => resolve());
  });

/**
 * Waits on the animation frameloop rather than on `setTimeout`.
 *
 * `waitFor` polls with `setTimeout`, and RTL only advances a faked clock for
 * that poll when `jest` is a global — under Vitest it is not, so any `waitFor`
 * in a fake-timer test hangs until the suite kills it. Motion drives its
 * transitions off `requestAnimationFrame`, which is left real here, so stepping
 * frames waits for exactly the thing that has to happen and nothing else.
 */
const waitForElement = async (query: () => HTMLElement | null) => {
  for (let frame = 0; frame < MAX_TRANSITION_FRAMES; frame++) {
    const found = query();
    if (found) {
      return found;
    }
    await act(async () => {
      await nextFrame();
    });
  }
  throw new Error(
    `Element never appeared within ${MAX_TRANSITION_FRAMES} animation frames`
  );
};

/** Fully controlled wrapper mirroring real-world usage of selectedApps + onChange. */
const ControlledStack = ({
  onChangeSpy,
}: {
  onChangeSpy: (ids: number[]) => void;
}) => {
  const [selected, setSelected] = useState<number[]>([]);
  return (
    <AppDownloadStack
      apps={apps}
      isExpanded
      onChange={(ids: number[]) => {
        setSelected(ids);
        onChangeSpy(ids);
      }}
      selectedApps={selected}
    />
  );
};

describe("AppDownloadStack", () => {
  it("renders without throwing", () => {
    const { container } = render(<AppDownloadStack />);
    expect(container).toBeInTheDocument();
  });

  it("expands the app selector on trigger click", async () => {
    const user = userEvent.setup();
    render(<AppDownloadStack apps={apps} title="My Apps" />);

    await user.click(
      screen.getByRole("button", { name: "Expand app selection" })
    );

    expect(screen.getByText("My Apps")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /GitHub/ })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /Figma/ })).toBeInTheDocument();
  });

  it("collapses the selector when the header is clicked again", async () => {
    const user = userEvent.setup();
    render(<AppDownloadStack apps={apps} title="My Apps" />);

    await user.click(
      screen.getByRole("button", { name: "Expand app selection" })
    );
    await user.click(screen.getByText("My Apps"));

    await waitFor(() =>
      expect(
        screen.getByRole("button", { name: "Expand app selection" })
      ).toBeInTheDocument()
    );
  });

  it("toggles app selection cumulatively and calls onChange", async () => {
    const user = userEvent.setup();
    const onChangeSpy = vi.fn();
    render(<ControlledStack onChangeSpy={onChangeSpy} />);

    await user.click(screen.getByRole("button", { name: /GitHub/ }));
    expect(onChangeSpy).toHaveBeenLastCalledWith([1]);

    await user.click(screen.getByRole("button", { name: /Figma/ }));
    expect(onChangeSpy).toHaveBeenLastCalledWith([1, 2]);

    await user.click(screen.getByRole("button", { name: /GitHub/ }));
    expect(onChangeSpy).toHaveBeenLastCalledWith([2]);
  });

  it("disables the download button until an app is selected", async () => {
    const user = userEvent.setup();
    render(<AppDownloadStack apps={apps} />);

    await user.click(
      screen.getByRole("button", { name: "Expand app selection" })
    );

    expect(
      screen.getByRole("button", { name: "Download Selected" })
    ).toBeDisabled();

    await user.click(screen.getByRole("button", { name: /GitHub/ }));

    expect(
      screen.getByRole("button", { name: "Download Selected" })
    ).toBeEnabled();
  });

  it("runs the full download flow and calls onDownload, resetting after completion", async () => {
    // This test used to sleep through the flow in real time. The component gates
    // itself on two `setTimeout`s — 3000ms of simulated downloading, then 1000ms
    // before it resets — so `waitFor` spent four wall-clock seconds polling for
    // state that only a clock could produce. That is 80% of the default 5s
    // budget spent idle, which is why it needed a hand-written 10s timeout and
    // still sat one slow CI runner away from failing.
    //
    // Only `setTimeout` is faked. Motion's transitions stay on the real
    // frameloop, so the `AnimatePresence mode="wait"` handoffs between the three
    // labels play exactly as they did before — they were never the expensive
    // part, and driving them off a faked `requestAnimationFrame` proved brittle.
    // What is skipped is only the dead time between them.
    vi.useFakeTimers({ toFake: ["clearTimeout", "setTimeout"] });

    try {
      const onDownload = vi.fn();
      render(<AppDownloadStack apps={apps} onDownload={onDownload} />);

      // `fireEvent`, not `userEvent`, only because of the fake clock: RTL's
      // async wrapper drains its microtask queue behind a `setTimeout(0)` that
      // it only advances when `jest` is a global, so under Vitest's fake timers
      // every `await user.click(...)` deadlocks. These are plain button clicks
      // with no pointer sequence worth simulating, so nothing is lost — the
      // `userEvent` paths through this component are covered by the tests above.
      fireEvent.click(
        screen.getByRole("button", { name: "Expand app selection" })
      );
      await waitForElement(() =>
        screen.queryByRole("button", { name: /GitHub/ })
      );

      fireEvent.click(screen.getByRole("button", { name: /GitHub/ }));
      fireEvent.click(
        screen.getByRole("button", { name: "Download Selected" })
      );

      expect(onDownload).toHaveBeenCalledWith([1]);
      expect(
        await waitForElement(() => screen.queryByText("Downloading..."))
      ).toBeInTheDocument();

      // Past the download timeout the complete label takes over...
      skipGate(DOWNLOAD_DURATION_MS);
      expect(
        await waitForElement(() => screen.queryByText("Download Complete!"))
      ).toBeInTheDocument();

      // ...and past the reset delay the whole thing collapses back to its
      // trigger.
      skipGate(RESET_DELAY_MS);
      expect(
        await waitForElement(() =>
          screen.queryByRole("button", { name: "Expand app selection" })
        )
      ).toBeInTheDocument();
    } finally {
      vi.useRealTimers();
    }
  });

  it("supports controlled selectedApps and isExpanded", () => {
    const noSelection: number[] = [];
    render(
      <AppDownloadStack
        apps={apps}
        isExpanded
        onChange={vi.fn()}
        selectedApps={noSelection}
      />
    );

    expect(screen.getByRole("button", { name: /GitHub/ })).toBeInTheDocument();
    // Controlled + expanded: renders the selector panel directly, no toggle needed.
    expect(
      screen.getByRole("button", { name: "Download Selected" })
    ).toBeDisabled();
  });
});

"use client";

import SmoothButton from "@repo/smoothui/components/smooth-button";
import { ChevronDown } from "lucide-react";
import {
  AnimatePresence,
  motion,
  useAnimation,
  useReducedMotion,
} from "motion/react";
import { useCallback, useMemo, useState } from "react";

export interface AppData {
  icon: string;
  id: number;
  name: string;
}

export interface AppDownloadStackProps {
  apps?: AppData[];
  className?: string;
  isExpanded?: boolean;
  onChange?: (selected: number[]) => void;
  onDownload?: (selected: number[]) => void;
  onExpandChange?: (expanded: boolean) => void;
  selectedApps?: number[];
  title?: string;
}

const DOWNLOAD_DURATION_MS = 3000;
const RESET_DELAY_MS = 1000;
const ROTATION_MULTIPLIER = 8;
const TRANSLATION_MULTIPLIER = 3;
const BASE_Z_INDEX = 40;
const Z_INDEX_STEP = 10;
const HOVER_X_MULTIPLIER = 10;
const HOVER_Y_MULTIPLIER = 10;
const FLOAT_AMPLITUDE = 5;
const FLOAT_DURATION = 2;
const FLOAT_DELAY_MULTIPLIER = 0.2;
const STAGGER_DELAY_MULTIPLIER = 0.1;
const TRANSITION_DURATION = 0.3;
const CHECKMARK_TRANSITION_DURATION = 0.3;

/**
 * Placeholder icons only — pass your own `apps` in anything you ship. URLs are
 * literal rather than imported from `@smoothui/data` so the component stays
 * self-contained when the registry copies it into someone else's project.
 */
const ICON_BASE = "https://ik.imagekit.io/16u211libb/smoothui/app-icons";

const defaultApps: AppData[] = [
  { icon: `${ICON_BASE}/safari.png?tr=w-128`, id: 1, name: "Safari" },
  { icon: `${ICON_BASE}/photos.png?tr=w-128`, id: 2, name: "Photos" },
  { icon: `${ICON_BASE}/podcasts.png?tr=w-128`, id: 3, name: "Podcasts" },
  { icon: `${ICON_BASE}/calendar.png?tr=w-128`, id: 4, name: "Calendar" },
];

export default function AppDownloadStack({
  apps = defaultApps,
  title = "Starter Mac",
  selectedApps: controlledSelected,
  onChange,
  onDownload,
  isExpanded: controlledExpanded,
  onExpandChange,
  className = "",
}: AppDownloadStackProps) {
  const [internalExpanded, setInternalExpanded] = useState(false);
  const [internalSelected, setInternalSelected] = useState<number[]>([]);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadComplete, setDownloadComplete] = useState(false);
  const shineControls = useAnimation();
  const shouldReduceMotion = useReducedMotion();

  const isExpanded =
    controlledExpanded === undefined ? internalExpanded : controlledExpanded;
  const selected = controlledSelected ?? internalSelected;

  const setExpanded = (val: boolean) => {
    if (onExpandChange) {
      onExpandChange(val);
    } else {
      setInternalExpanded(val);
    }
  };

  const toggleApp = useCallback(
    (id: number) => {
      const newSelected = selected.includes(id)
        ? selected.filter((appId) => appId !== id)
        : [...selected, id];
      if (onChange) {
        onChange(newSelected);
      } else {
        setInternalSelected(newSelected);
      }
    },
    [selected, onChange]
  );

  const handleDownload = useCallback(() => {
    setIsDownloading(true);
    if (onDownload) {
      onDownload(selected);
    }
    if (!shouldReduceMotion) {
      shineControls.start({
        transition: {
          duration: 1,
          ease: "linear",
          repeat: Number.POSITIVE_INFINITY,
        },
        x: ["0%", "100%"],
      });
    }
    setTimeout(() => {
      shineControls.stop();
      setDownloadComplete(true);
      setTimeout(() => {
        if (onExpandChange) {
          onExpandChange(false);
        } else {
          setInternalExpanded(false);
        }
        if (onChange) {
          onChange([]);
        } else {
          setInternalSelected([]);
        }
        setIsDownloading(false);
        setDownloadComplete(false);
      }, RESET_DELAY_MS);
    }, DOWNLOAD_DURATION_MS);
  }, [
    shineControls,
    selected,
    onDownload,
    onChange,
    onExpandChange,
    shouldReduceMotion,
  ]);

  const stackVariants = useMemo(
    // biome-ignore lint/suspicious/noExplicitAny: Variants type requires flexible return
    (): Record<string, (i: number) => any> => ({
      float: (i: number) =>
        shouldReduceMotion
          ? { y: 0 }
          : {
              transition: {
                y: {
                  delay: i * FLOAT_DELAY_MULTIPLIER,
                  duration: FLOAT_DURATION,
                  ease: [0.645, 0.045, 0.355, 1],
                  repeat: Number.POSITIVE_INFINITY,
                },
              },
              y: [0, -FLOAT_AMPLITUDE, 0],
            },
      hover: (i: number) =>
        shouldReduceMotion
          ? {
              rotate: 0,
              x: 0,
              y: 0,
              zIndex: BASE_Z_INDEX - i * Z_INDEX_STEP,
            }
          : {
              rotate: 0,
              x: i * HOVER_X_MULTIPLIER,
              y: -i * HOVER_Y_MULTIPLIER,
              zIndex: BASE_Z_INDEX - i * Z_INDEX_STEP,
            },
      initial: (i: number) =>
        shouldReduceMotion
          ? {
              rotate: 0,
              x: 0,
              y: 0,
              zIndex: BASE_Z_INDEX - i * Z_INDEX_STEP,
            }
          : {
              rotate:
                i % 2 === 0
                  ? -ROTATION_MULTIPLIER * (i + 1)
                  : ROTATION_MULTIPLIER * (i + 1),
              x:
                i % 2 === 0
                  ? -TRANSLATION_MULTIPLIER * (i + 1)
                  : TRANSLATION_MULTIPLIER * (i + 1),
              y: 0,
              zIndex: BASE_Z_INDEX - i * Z_INDEX_STEP,
            },
    }),
    [shouldReduceMotion]
  );

  return (
    <div
      className={`flex h-auto flex-col items-center justify-center ${className}`}
    >
      <motion.div
        className="flex flex-col items-center justify-center"
        layout={!shouldReduceMotion}
      >
        <AnimatePresence mode="wait">
          {!(isExpanded || isDownloading) && (
            <motion.button
              aria-label="Expand app selection"
              className="group relative isolate flex h-16 w-16 cursor-pointer items-center justify-center"
              key="initial-stack"
              layout={!shouldReduceMotion}
              onClick={() => setExpanded(true)}
              whileHover={shouldReduceMotion ? {} : "hover"}
            >
              {apps.map((app, index) => (
                <motion.img
                  alt={`${app.name} Logo`}
                  animate={
                    shouldReduceMotion ? "initial" : ["initial", "float"]
                  }
                  className="absolute inset-0 rounded-xl border-none"
                  custom={index}
                  draggable={false}
                  height={64}
                  initial="initial"
                  key={app.id}
                  layoutId={
                    shouldReduceMotion ? undefined : `app-icon-${app.id}`
                  }
                  src={app.icon}
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { duration: TRANSITION_DURATION }
                  }
                  variants={stackVariants}
                  whileHover={shouldReduceMotion ? {} : "hover"}
                  width={64}
                />
              ))}
            </motion.button>
          )}

          {isExpanded && !isDownloading && (
            <motion.div
              animate={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }
              }
              className="flex flex-col items-center gap-2"
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, scale: 0.8 }
              }
              initial={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.8 }
              }
              key="app-selector"
              layout={!shouldReduceMotion}
            >
              <button
                className="flex w-full cursor-pointer items-center justify-between px-0.5"
                onClick={() => setExpanded(false)}
                type="button"
              >
                <p className="my-0 font-medium leading-0">{title}</p>
                <div className="flex items-center gap-1">
                  <p className="my-0 font-medium leading-0">
                    {selected.length}
                  </p>
                  <ChevronDown className="text-mauve-11" size={16} />
                </div>
              </button>
              <motion.ul className="grid grid-cols-2 gap-3">
                {apps.map((app, index) => (
                  <motion.li
                    animate={
                      shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }
                    }
                    className="relative flex h-[80px] w-[80px]"
                    initial={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 0, y: 20 }
                    }
                    key={app.id}
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : {
                            delay: index * STAGGER_DELAY_MULTIPLIER,
                            duration: 0.25,
                          }
                    }
                  >
                    <div
                      className={`pointer-events-none absolute top-2 right-2 flex h-4 w-4 items-center justify-center rounded-full border border-solid ${
                        selected.includes(app.id)
                          ? "border-blue-500 bg-blue-500"
                          : "border-white/60"
                      }`}
                    >
                      {selected.includes(app.id) && (
                        <motion.svg
                          animate={{ pathLength: 1 }}
                          className="z-1 h-3 w-3"
                          fill="none"
                          initial={{ pathLength: 0 }}
                          stroke="white"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth="2"
                          transition={{
                            duration: CHECKMARK_TRANSITION_DURATION,
                          }}
                          viewBox="0 0 24 24"
                          xmlns="http://www.w3.org/2000/svg"
                        >
                          <title>Checkmark</title>
                          <motion.path d="M5 13l4 4L19 7" />
                        </motion.svg>
                      )}
                    </div>
                    <button
                      className={`group flex h-full w-full flex-col items-center justify-center gap-1 rounded-xl border-2 border-transparent bg-background/80 p-2 transition-all duration-200 hover:border-blue-500 ${
                        selected.includes(app.id)
                          ? "border-blue-500 bg-blue-500/10"
                          : ""
                      }`}
                      onClick={() => toggleApp(app.id)}
                      type="button"
                    >
                      <img
                        alt={app.name}
                        className="rounded-lg"
                        draggable={false}
                        height={40}
                        src={app.icon}
                        width={40}
                      />
                      <span className="font-medium text-foreground text-xs">
                        {app.name}
                      </span>
                    </button>
                  </motion.li>
                ))}
              </motion.ul>
              <SmoothButton
                className="mt-4 w-full"
                color="blue"
                disabled={selected.length === 0}
                onClick={handleDownload}
                type="button"
                variant="solid"
              >
                Download Selected
              </SmoothButton>
            </motion.div>
          )}

          {isDownloading && !downloadComplete && (
            <motion.div
              animate={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }
              }
              className="flex flex-col items-center gap-4"
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, scale: 0.8 }
              }
              initial={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.8 }
              }
              key="downloading"
              layout={!shouldReduceMotion}
            >
              <div className="relative flex h-16 w-16 items-center justify-center">
                <motion.div
                  animate={shineControls}
                  className="absolute inset-0 rounded-xl bg-blue-500/20"
                  style={{ x: 0 }}
                />
                {apps.map((app, index) => (
                  <motion.img
                    alt={`${app.name} Logo`}
                    animate={
                      shouldReduceMotion ? "initial" : ["initial", "float"]
                    }
                    className="absolute inset-0 rounded-xl border-none"
                    custom={index}
                    draggable={false}
                    height={64}
                    initial="initial"
                    key={app.id}
                    layoutId={
                      shouldReduceMotion ? undefined : `app-icon-${app.id}`
                    }
                    src={app.icon}
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : { duration: TRANSITION_DURATION }
                    }
                    variants={stackVariants}
                    width={64}
                  />
                ))}
              </div>
              <span className="font-semibold text-blue-500">
                Downloading...
              </span>
            </motion.div>
          )}

          {downloadComplete ? (
            <motion.div
              animate={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }
              }
              className="flex flex-col items-center gap-4"
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, scale: 0.8 }
              }
              initial={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.8 }
              }
              key="download-complete"
              layout={!shouldReduceMotion}
            >
              <span className="font-semibold text-green-500">
                Download Complete!
              </span>
            </motion.div>
          ) : null}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}

