import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import {
  type Canvas2DMock,
  flushFrames,
  installCanvas2DMock,
  installIntersectionObserverMock,
  installMediaElementMock,
  pendingFrameCount,
  uninstallCanvas2DMock,
  uninstallIntersectionObserverMock,
  uninstallMediaElementMock,
} from "../../../test-utils/canvas-2d";
import { fireEvent, render } from "../../../test-utils/render";
import AsciiRender from "../index";

const IMAGE_SOURCE = {
  src: "https://example.com/image.png",
  type: "image",
} as const;
const VIDEO_SOURCE = {
  src: "https://example.com/video.mp4",
  type: "video",
} as const;

const COLUMNS = 20;
const MEDIA_WIDTH = 64;
const MEDIA_HEIGHT = 48;
/** round(columns * height * CHAR_ASPECT / width) */
const ROWS = 8;

describe("AsciiRender", () => {
  it("renders without throwing", () => {
    const { container } = render(
      <AsciiRender alt="A sample image" source={IMAGE_SOURCE} />
    );
    expect(container).toBeInTheDocument();
  });

  it("renders with a video source and source color mode", () => {
    const { container } = render(
      <AsciiRender alt="A sample video" color="source" source={VIDEO_SOURCE} />
    );
    expect(container).toBeInTheDocument();
  });
});

describe("AsciiRender sampling", () => {
  it("has no accessibility violations", async () => {
    const { container } = render(
      <AsciiRender alt="A photo" columns={COLUMNS} source={IMAGE_SOURCE} />
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  let canvas2d: Canvas2DMock;

  beforeEach(() => {
    canvas2d = installCanvas2DMock();
    installMediaElementMock({
      naturalHeight: MEDIA_HEIGHT,
      naturalWidth: MEDIA_WIDTH,
    });
  });

  afterEach(() => {
    uninstallMediaElementMock();
    uninstallCanvas2DMock();
  });

  const preOf = (container: HTMLElement) => {
    const pre = container.querySelector("pre");
    if (!pre) {
      throw new Error("expected a pre");
    }
    return pre;
  };

  it("rasterises an image into a character grid", () => {
    const { container } = render(
      <AsciiRender alt="A photo" columns={COLUMNS} source={IMAGE_SOURCE} />
    );

    const context = canvas2d.last();
    expect(context?.drawImage).toHaveBeenCalled();
    expect(context?.getImageData).toHaveBeenCalledWith(0, 0, COLUMNS, ROWS);
    expect(context?.canvas.width).toBe(COLUMNS);
    expect(context?.canvas.height).toBe(ROWS);

    const text = preOf(container).textContent ?? "";
    expect(text).toHaveLength(ROWS * (COLUMNS + 1));
    expect(text.split("\n")).toHaveLength(ROWS + 1);
    // A real luminance read produces a mix of glyphs, not one repeated char.
    expect(new Set(text.replace(/\n/g, "")).size).toBeGreaterThan(1);
  });

  it("inverts the luminance-to-glyph mapping", () => {
    const { container: plain } = render(
      <AsciiRender alt="A photo" columns={COLUMNS} source={IMAGE_SOURCE} />
    );
    const { container: inverted } = render(
      <AsciiRender
        alt="A photo"
        columns={COLUMNS}
        invert
        source={IMAGE_SOURCE}
      />
    );

    expect(preOf(inverted).textContent).not.toBe(preOf(plain).textContent);
  });

  it("falls back to the default ramp for a single-character charset", () => {
    const { container: single } = render(
      <AsciiRender
        alt="A photo"
        charset="#"
        columns={COLUMNS}
        source={IMAGE_SOURCE}
      />
    );
    const { container: standard } = render(
      <AsciiRender alt="A photo" columns={COLUMNS} source={IMAGE_SOURCE} />
    );

    expect(preOf(single).textContent).toBe(preOf(standard).textContent);
  });

  it("uses a custom ramp", () => {
    const { container } = render(
      <AsciiRender
        alt="A photo"
        charset="ab"
        columns={COLUMNS}
        source={IMAGE_SOURCE}
      />
    );
    expect(preOf(container).textContent?.replace(/\n/g, "")).toMatch(/^[ab]+$/);
  });

  it("tints the glyphs with the frame in source colour mode", () => {
    const { container } = render(
      <AsciiRender
        alt="A photo"
        color="source"
        columns={COLUMNS}
        source={IMAGE_SOURCE}
      />
    );
    expect(preOf(container).style.backgroundImage).toContain(
      "data:image/png;base64"
    );
  });

  it("clamps the column count to the supported range", () => {
    render(<AsciiRender alt="A photo" columns={9000} source={IMAGE_SOURCE} />);
    expect(canvas2d.last()?.canvas.width).toBe(240);
  });

  it("holds a single frame for an image source", () => {
    render(
      <AsciiRender alt="A photo" columns={COLUMNS} source={IMAGE_SOURCE} />
    );
    expect(pendingFrameCount()).toBe(0);
  });

  it("drives a video source frame by frame at the requested fps", () => {
    render(
      <AsciiRender
        alt="A clip"
        columns={COLUMNS}
        fps={24}
        source={VIDEO_SOURCE}
      />
    );

    const context = canvas2d.last();
    const initialDraws = context?.drawImage.mock.calls.length ?? 0;
    expect(initialDraws).toBe(1);
    expect(pendingFrameCount()).toBeGreaterThan(0);

    // 24fps is a 41.7ms budget, so a 16ms frame is skipped and a later one draws.
    flushFrames(1);
    expect(context?.drawImage.mock.calls.length).toBe(initialDraws);
    flushFrames(3);
    expect(context?.drawImage.mock.calls.length).toBeGreaterThan(initialDraws);
  });

  it("holds the frame when paused", () => {
    render(
      <AsciiRender
        alt="A clip"
        columns={COLUMNS}
        paused
        source={VIDEO_SOURCE}
      />
    );
    expect(canvas2d.last()?.drawImage).toHaveBeenCalledTimes(1);
    expect(pendingFrameCount()).toBe(0);
  });

  it("cancels the loop on unmount", () => {
    const { unmount } = render(
      <AsciiRender alt="A clip" columns={COLUMNS} source={VIDEO_SOURCE} />
    );
    expect(pendingFrameCount()).toBeGreaterThan(0);

    unmount();
    expect(pendingFrameCount()).toBe(0);
  });

  it("falls back when the media fails to load", () => {
    const { container } = render(
      <AsciiRender alt="A photo" columns={COLUMNS} source={IMAGE_SOURCE} />
    );
    const image = container.querySelector("img");
    if (!image) {
      throw new Error("expected an img");
    }

    fireEvent.error(image);

    expect(preOf(container).className).toContain("hidden");
    expect(image.className).toContain("relative");
  });
});

describe("AsciiRender visibility", () => {
  afterEach(() => {
    uninstallIntersectionObserverMock();
    uninstallMediaElementMock();
    uninstallCanvas2DMock();
  });

  it("holds the frame while off screen", () => {
    installCanvas2DMock();
    installMediaElementMock({
      naturalHeight: MEDIA_HEIGHT,
      naturalWidth: MEDIA_WIDTH,
    });
    const intersection = installIntersectionObserverMock();

    render(
      <AsciiRender alt="A clip" columns={COLUMNS} source={VIDEO_SOURCE} />
    );
    expect(pendingFrameCount()).toBeGreaterThan(0);

    intersection.trigger(false);
    expect(pendingFrameCount()).toBe(0);
  });
});

describe("AsciiRender without a 2D context", () => {
  afterEach(() => {
    uninstallMediaElementMock();
    uninstallCanvas2DMock();
  });

  it("falls back when the canvas cannot be sampled", () => {
    installCanvas2DMock({ supported: false });
    installMediaElementMock();

    const { container } = render(
      <AsciiRender alt="A photo" source={IMAGE_SOURCE} />
    );
    expect(container.querySelector("pre")?.className).toContain("hidden");
  });

  it("holds at zero size when the media has no intrinsic dimensions", () => {
    installCanvas2DMock();
    installMediaElementMock({ naturalHeight: 0, naturalWidth: 0 });

    const { container } = render(
      <AsciiRender alt="A photo" source={IMAGE_SOURCE} />
    );
    expect(container.querySelector("pre")?.textContent).toBe("");
  });
});

"use client";

import { cn } from "@repo/smoothui-utils";
import { useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export type AsciiColorMode = "mono" | "source";

export interface AsciiRenderSource {
  /** URL of the image or video to sample. Must allow cross-origin reads. */
  src: string;
  /** Kind of media behind `src`. */
  type: "image" | "video";
}

export interface AsciiRenderProps {
  /** Description of the media. Exposed to assistive technology. */
  alt: string;
  /** Character ramp ordered dense to sparse. */
  charset?: string;
  /** Extra classes for the wrapper. */
  className?: string;
  /** `mono` paints one theme colour, `source` tints the glyphs with the frame. */
  color?: AsciiColorMode;
  /** Number of character columns sampled across the frame. */
  columns?: number;
  /** Glyph size in pixels. */
  fontSize?: number;
  /** Frames per second for video sources. */
  fps?: number;
  /** Flip the luminance-to-character mapping. */
  invert?: boolean;
  /** Hold the current frame without tearing down the renderer. */
  paused?: boolean;
  /** Media descriptor. */
  source: AsciiRenderSource;
}

type RenderStatus = "fallback" | "loading" | "ready";

const DEFAULT_CHARSET = "@%#*+=-:. ";
const DEFAULT_COLUMNS = 80;
const DEFAULT_FONT_SIZE = 10;
const DEFAULT_FPS = 24;
const MIN_COLUMNS = 8;
const MAX_COLUMNS = 240;
const MIN_FPS = 1;
const MAX_FPS = 60;
const CHAR_ASPECT = 0.5;
const CHANNELS = 4;
const MAX_CHANNEL = 255;
const LUMA_R = 0.2126;
const LUMA_G = 0.7152;
const LUMA_B = 0.0722;
const MS_PER_SECOND = 1000;
const NEWLINE = "\n";
const VISIBILITY_MARGIN = "0px 0px 10% 0px";

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(max, value));

const buildAscii = (
  data: Uint8ClampedArray,
  columns: number,
  rows: number,
  charset: string,
  invert: boolean
) => {
  const lastIndex = charset.length - 1;
  const glyphs: string[] = [];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < columns; x++) {
      const offset = (y * columns + x) * CHANNELS;
      const luminance =
        (data[offset] * LUMA_R +
          data[offset + 1] * LUMA_G +
          data[offset + 2] * LUMA_B) /
        MAX_CHANNEL;
      const level = invert ? 1 - luminance : luminance;
      glyphs.push(charset[clamp(Math.round(level * lastIndex), 0, lastIndex)]);
    }
    glyphs.push(NEWLINE);
  }
  return glyphs.join("");
};

const AsciiRender = ({
  alt,
  charset = DEFAULT_CHARSET,
  className,
  color = "mono",
  columns = DEFAULT_COLUMNS,
  fontSize = DEFAULT_FONT_SIZE,
  fps = DEFAULT_FPS,
  invert = false,
  paused = false,
  source,
}: AsciiRenderProps) => {
  const shouldReduceMotion = useReducedMotion();
  const containerRef = useRef<HTMLDivElement>(null);
  const preRef = useRef<HTMLPreElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [status, setStatus] = useState<RenderStatus>("loading");
  const [isVisible, setIsVisible] = useState(true);

  const { src: sourceSrc, type: sourceType } = source;
  const safeCharset = charset.length > 1 ? charset : DEFAULT_CHARSET;
  const safeColumns = clamp(Math.round(columns), MIN_COLUMNS, MAX_COLUMNS);
  const safeFps = clamp(Math.round(fps), MIN_FPS, MAX_FPS);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof IntersectionObserver === "undefined") {
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          setIsVisible(entry.isIntersecting);
        }
      },
      { rootMargin: VISIBILITY_MARGIN }
    );
    observer.observe(container);
    return () => {
      observer.disconnect();
    };
  }, []);

  useEffect(() => {
    const pre = preRef.current;
    const media = sourceType === "video" ? videoRef.current : imageRef.current;
    if (!(pre && media && sourceSrc)) {
      return;
    }

    const grid = document.createElement("canvas");
    const context = grid.getContext("2d", { willReadFrequently: true });
    if (!context) {
      setStatus("fallback");
      return;
    }

    const video = sourceType === "video" ? (media as HTMLVideoElement) : null;
    const image = sourceType === "image" ? (media as HTMLImageElement) : null;
    let frame = 0;
    let lastDrawnAt = 0;
    let isCancelled = false;

    const naturalSize = () => {
      if (video) {
        return { height: video.videoHeight, width: video.videoWidth };
      }
      return {
        height: image?.naturalHeight ?? 0,
        width: image?.naturalWidth ?? 0,
      };
    };

    const drawFrame = () => {
      const { height: mediaHeight, width: mediaWidth } = naturalSize();
      if (mediaWidth === 0 || mediaHeight === 0) {
        return false;
      }
      const rows = Math.max(
        1,
        Math.round((safeColumns * mediaHeight * CHAR_ASPECT) / mediaWidth)
      );
      grid.width = safeColumns;
      grid.height = rows;
      context.clearRect(0, 0, safeColumns, rows);
      context.drawImage(media, 0, 0, safeColumns, rows);

      const { data } = context.getImageData(0, 0, safeColumns, rows);
      pre.textContent = buildAscii(
        data,
        safeColumns,
        rows,
        safeCharset,
        invert
      );
      pre.style.backgroundImage =
        color === "source" ? `url(${grid.toDataURL()})` : "";
      return true;
    };

    const safeDraw = () => {
      try {
        return drawFrame();
      } catch {
        setStatus("fallback");
        return false;
      }
    };

    const tick = (time: number) => {
      if (isCancelled) {
        return;
      }
      const interval = MS_PER_SECOND / safeFps;
      if (time - lastDrawnAt >= interval) {
        lastDrawnAt = time;
        if (!safeDraw()) {
          return;
        }
      }
      frame = requestAnimationFrame(tick);
    };

    const start = () => {
      if (isCancelled) {
        return;
      }
      if (!safeDraw()) {
        return;
      }
      setStatus("ready");
      const isStatic = !video || shouldReduceMotion || paused || !isVisible;
      if (isStatic) {
        video?.pause();
        return;
      }
      const playback = video.play();
      playback?.catch(() => {
        setStatus("fallback");
      });
      frame = requestAnimationFrame(tick);
    };

    const handleError = () => {
      if (!isCancelled) {
        setStatus("fallback");
      }
    };

    if (video) {
      if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) {
        start();
      } else {
        video.addEventListener("loadeddata", start, { once: true });
      }
      video.addEventListener("error", handleError);
    } else if (image) {
      if (image.complete) {
        start();
      } else {
        image.addEventListener("load", start, { once: true });
      }
      image.addEventListener("error", handleError);
    }

    return () => {
      isCancelled = true;
      cancelAnimationFrame(frame);
      video?.removeEventListener("loadeddata", start);
      video?.removeEventListener("error", handleError);
      video?.pause();
      image?.removeEventListener("load", start);
      image?.removeEventListener("error", handleError);
      grid.width = 0;
      grid.height = 0;
    };
  }, [
    color,
    invert,
    isVisible,
    paused,
    safeCharset,
    safeColumns,
    safeFps,
    shouldReduceMotion,
    sourceSrc,
    sourceType,
  ]);

  const isFallback = status === "fallback";
  const mediaClassName = cn(
    "h-full w-full object-contain",
    isFallback ? "relative" : "pointer-events-none absolute inset-0 opacity-0"
  );

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-xl bg-background",
        className
      )}
      ref={containerRef}
    >
      {sourceType === "video" ? (
        <video
          aria-hidden="true"
          className={mediaClassName}
          crossOrigin="anonymous"
          loop
          muted
          playsInline
          preload="auto"
          ref={videoRef}
          src={sourceSrc}
          tabIndex={-1}
        />
      ) : (
        <img
          alt=""
          aria-hidden="true"
          className={mediaClassName}
          crossOrigin="anonymous"
          ref={imageRef}
          src={sourceSrc}
        />
      )}

      <pre
        aria-hidden="true"
        className={cn(
          "m-0 select-none whitespace-pre font-mono",
          color === "mono" ? "text-foreground" : "text-transparent",
          isFallback ? "hidden" : "block"
        )}
        ref={preRef}
        style={{
          backgroundClip: color === "source" ? "text" : undefined,
          backgroundSize: "100% 100%",
          fontSize,
          imageRendering: "pixelated",
          lineHeight: 1,
          WebkitBackgroundClip: color === "source" ? "text" : undefined,
        }}
      />

      <span className="sr-only">{alt}</span>
    </div>
  );
};

export default AsciiRender;

