  status: AvatarStatusValue;
}

const SIZE_CLASS: Record<AvatarSize, string> = {
  lg: "size-10 text-sm",
  md: "size-8 text-xs",
  sm: "size-6 text-[10px]",
};

const STATUS_DOT_SIZE: Record<AvatarSize, string> = {
