/** Presence dot — place inside `AvatarRoot`. */
export const AvatarStatus = ({ className, status }: AvatarStatusProps) => {
  const size = useContext(AvatarSizeContext);

  return (
    <span
      aria-label={status}
      className={cn(
        "absolute right-0 bottom-0 rounded-full ring-2 ring-background",
