      data-status={status}
      role="img"
    />
  );
};

/** `+N` chip for avatars hidden by `AvatarGroup max`. */
export const AvatarGroupOverflow = ({
  className,
  count,
}: AvatarGroupOverflowProps) => {
  const group = useContext(AvatarGroupContext);

  return (
    <span
      aria-label={`${count} more`}
