      data-status={status}
      ref={hostRef}
      role="status"
    >
      {showPulse ? (
        <motion.span
          animate={{ opacity: [0.55, 0], scale: [1, 1.85] }}
          aria-hidden
          className={cn(
            "absolute inset-0 rounded-full",
            DOT_COLOR[status],
            LOOP_CLASS
          )}
          transition={loopTransition(
            { duration: 1.4, ease: EASE_OUT },
            LOOP_REPEAT_DELAY.pulse
          )}
        />
      ) : null}
    </span>
  );
};

