import { describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { act, fireEvent, render, screen } from "../../../test-utils/render";
import ButtonCopy from "../index";

describe("ButtonCopy", () => {
  it("allows retry after rejection without reporting success", async () => {
    const onCopy = vi
      .fn()
      .mockRejectedValueOnce(new Error("Denied"))
      .mockResolvedValue(undefined);
    render(<ButtonCopy onCopy={onCopy} loadingDuration={0} />);
    await act(async () =>
      fireEvent.click(screen.getByRole("button", { name: "Copy" }))
    );
    const retry = screen.getByRole("button", {
      name: "Copy failed. Try again",
    });
    expect(retry).toBeEnabled();
    expect(
      screen.queryByRole("button", { name: "Copied" })
    ).not.toBeInTheDocument();
    await act(async () => fireEvent.click(retry));
    expect(
      await screen.findByRole("button", { name: "Copied" })
    ).toBeInTheDocument();
    expect(onCopy).toHaveBeenCalledTimes(2);
  });

  it("does not schedule success timers after an in-flight copy unmounts", async () => {
    let resolveCopy: (() => void) | undefined;
    const pending = new Promise<void>((resolve) => {
      resolveCopy = resolve;
    });
    const { unmount } = render(<ButtonCopy onCopy={() => pending} />);
    await act(async () =>
      fireEvent.click(screen.getByRole("button", { name: "Copy" }))
    );
    unmount();
    const timerSpy = vi.spyOn(globalThis, "setTimeout");
    await act(async () => {
      resolveCopy?.();
      await pending;
    });
    expect(timerSpy).not.toHaveBeenCalled();
    timerSpy.mockRestore();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<ButtonCopy />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("renders without throwing", () => {
    const { container } = render(<ButtonCopy />);
    expect(container).toBeInTheDocument();
  });
});

"use client";

import SmoothButton from "@repo/smoothui/components/smooth-button";
import { Check, Copy, LoaderCircle } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

export interface ButtonCopyProps {
  className?: string;
  disabled?: boolean;
  duration?: number;
  idleIcon?: ReactNode;
  loadingDuration?: number;
  loadingIcon?: ReactNode;
  onCopy?: () => Promise<void> | void;
  successIcon?: ReactNode;
}

const defaultIcons = {
  idle: <Copy size={16} />,
  loading: (
    <LoaderCircle
      className="animate-spin motion-reduce:animate-none"
      size={16}
    />
  ),
  success: <Check size={16} />,
};

export default function ButtonCopy({
  onCopy,
  idleIcon = defaultIcons.idle,
  loadingIcon = defaultIcons.loading,
  successIcon = defaultIcons.success,
  className = "",
  duration = 2000,
  loadingDuration = 1000,
  disabled = false,
}: ButtonCopyProps) {
  const [buttonState, setButtonState] = useState<
    "idle" | "loading" | "success" | "error"
  >("idle");
  const shouldReduceMotion = useReducedMotion();

  const requestId = useRef(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(
    () => () => {
      requestId.current += 1;
      for (const timer of timers.current) {
        clearTimeout(timer);
      }
    },
    []
  );

  const handleClick = useCallback(async () => {
    const request = ++requestId.current;
    setButtonState("loading");
    try {
      await onCopy?.();
    } catch {
      if (request === requestId.current) {
        setButtonState("error");
      }
      return;
    }
    if (request !== requestId.current) {
      return;
    }
    timers.current = [
      setTimeout(() => setButtonState("success"), loadingDuration),
      setTimeout(() => setButtonState("idle"), loadingDuration + duration),
    ];
  }, [onCopy, loadingDuration, duration]);

  const icons = {
    error: idleIcon,
    idle: idleIcon,
    loading: loadingIcon,
    success: successIcon,
  };

  const ariaLabels = {
    error: "Copy failed. Try again",
    idle: "Copy",
    loading: "Copying...",
    success: "Copied",
  };

  return (
    <div className="flex justify-center">
      <SmoothButton
        aria-label={ariaLabels[buttonState]}
        aria-live="polite"
        className={`relative min-h-11 min-w-11 overflow-hidden bg-background p-3 ${className}`}
        disabled={
          buttonState === "loading" || buttonState === "success" || disabled
        }
        onClick={handleClick}
        shape="pill"
        size="icon"
        type="button"
        variant="outline"
      >
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            animate={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(0px)", opacity: 1, y: 0 }
            }
            className="flex w-full items-center justify-center"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { filter: "blur(10px)", opacity: 0, y: 25 }
            }
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(10px)", opacity: 0, y: -25 }
            }
            key={buttonState}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { bounce: 0, duration: 0.25, type: "spring" as const }
            }
          >
            {icons[buttonState]}
          </motion.span>
        </AnimatePresence>
      </SmoothButton>
    </div>
  );
}

