const isOn = (el: HTMLElement) =>
  el.getAttribute("aria-checked") === "true" ||
  el.hasAttribute("data-checked") ||
  el.getAttribute("data-state") === "checked";

describe.each([
  ["Base", CheckboxBase],
  ["Radix", CheckboxRadix],
] as const)("Checkbox (%s) uncontrolled", (_name, Checkbox) => {
