    expect(isOn(box)).toBe(false);
    await user.click(box);
    expect(isOn(box)).toBe(true);
    expect(box.querySelector("svg")).not.toBeNull();
    await user.click(box);
    expect(isOn(box)).toBe(false);
  });

  it("starts on with defaultChecked", () => {
